import { Injectable, inject } from '@angular/core';
import { Actions, createEffect, ofType } from '@ngrx/effects';
import { tap, withLatestFrom, mergeMap } from 'rxjs/operators';
import { Store } from '@ngrx/store';
import { of } from 'rxjs';
import * as CartActions from './cart.actions';
import { selectCartItems } from './cart.selectors';
import { applyPromoCode } from '../../../mocks/promo';

const CART_STORAGE_KEY = 'shop_cart_state';

@Injectable()
export class CartEffects {
  private readonly actions$ = inject(Actions);
  private readonly store = inject(Store);

  constructor() {
    this.initializePersistence();
  }

  private initializePersistence(): void {
    this.actions$
      .pipe(
        ofType(
          CartActions.addItem,
          CartActions.removeItem,
          CartActions.updateQuantity,
          CartActions.clearCart
        ),
        tap(() => {
          this.store.select(selectCartItems).subscribe((items) => {
            localStorage.setItem(CART_STORAGE_KEY, JSON.stringify(items));
          });
        })
      )
      .subscribe();
  }

  applyPromo$ = createEffect(() =>
    this.actions$.pipe(
      ofType(CartActions.applyPromoCode),
      withLatestFrom(this.store.select(selectCartItems)),
      mergeMap(([{ code }, items]) => {
        try {
          const normalized = code?.trim().toUpperCase() || '';
          const result = applyPromoCode(items, normalized);
          return of(CartActions.applyPromoSuccess({ result }));
        } catch (error) {
          const message = error instanceof Error ? error.message : 'Unable to apply promo code';
          return of(CartActions.applyPromoFailure({ error: message }));
        }
      })
    )
  );
}

import { Injectable } from '@angular/core';
import { OrderDetail, OrderSummary } from '../state/user/user.actions';

@Injectable({
  providedIn: 'root',
})
export class OrdersStorageService {
  private readonly ORDERS_KEY = 'userOrders';

  constructor() {
    // Initialize with empty orders if none exist
    if (!localStorage.getItem(this.ORDERS_KEY)) {
      localStorage.setItem(this.ORDERS_KEY, JSON.stringify([]));
    }
  }

  /**
   * Add a new order from checkout
   */
  addOrder(orderData: any): OrderDetail {
    const orders = this.getAllOrdersFromStorage();
    
    const newOrder: OrderDetail = {
      id: Date.now().toString(),
      date: new Date().toISOString(),
      total: orderData.total,
      status: 'en_cours',
      itemCount: orderData.items?.length || 0,
      items: (orderData.items || []).map((item: any) => ({
        productId: item.id,
        productName: item.name,
        quantity: item.quantity,
        price: item.price,
      })),
      subtotal: orderData.subtotal || (orderData.items || []).reduce((sum: number, item: any) => sum + (item.price * item.quantity), 0),
      tax: orderData.tax ?? orderData.taxes ?? 0,
      shipping: orderData.shipping || 0,
      deliveryAddress: {
        street: orderData.address?.street || '',
        city: orderData.address?.city || '',
        zipCode: orderData.address?.zipCode || '',
        country: orderData.address?.country || '',
      },
      deliveryOption: orderData.deliveryOption || 'standard',
      trackingUrl: `https://example.com/track/ORD-${Date.now()}`,
    };

    orders.push(newOrder);
    localStorage.setItem(this.ORDERS_KEY, JSON.stringify(orders));
    return newOrder;
  }

  /**
   * Get all orders
   */
  getAllOrders(): OrderSummary[] {
    return this.getAllOrdersFromStorage().map((order: OrderDetail) => ({
      id: order.id,
      date: order.date,
      total: order.total,
      status: order.status,
      itemCount: order.itemCount,
    }));
  }

  /**
   * Get a specific order by ID
   */
  getOrderById(orderId: string): OrderDetail | null {
    const orders = this.getAllOrdersFromStorage();
    return orders.find((order: OrderDetail) => order.id === orderId) || null;
  }

  /**
   * Get all orders from localStorage
   */
  private getAllOrdersFromStorage(): OrderDetail[] {
    const stored = localStorage.getItem(this.ORDERS_KEY);
    return stored ? JSON.parse(stored) : [];
  }
}

import { Injectable } from '@angular/core';
import { ProductsFilters, ProductsResponse } from './products.actions';

interface CacheEntry {
  filtersKey: string;
  data: ProductsResponse;
  timestamp: number;
}

@Injectable({ providedIn: 'root' })
export class ProductsCacheService {
  private readonly cache = new Map<string, CacheEntry>();

  buildKey(filters?: ProductsFilters): string {
    return JSON.stringify(filters ?? {});
  }

  get(filtersKey: string): CacheEntry | undefined {
    return this.cache.get(filtersKey);
  }

  set(filtersKey: string, data: ProductsResponse): void {
    this.cache.set(filtersKey, {
      filtersKey,
      data,
      timestamp: Date.now(),
    });
  }

  hasChanged(filtersKey: string, data: ProductsResponse): boolean {
    const existing = this.get(filtersKey);
    if (!existing) {
      return true;
    }
    if (existing.data.count !== data.count) {
      return true;
    }
    const existingIds = existing.data.results.map((p) => p.id);
    const incomingIds = data.results.map((p) => p.id);
    if (existingIds.length !== incomingIds.length) {
      return true;
    }
    for (let i = 0; i < existingIds.length; i += 1) {
      if (existingIds[i] !== incomingIds[i]) {
        return true;
      }
    }
    return false;
  }
}

