        <div class="flex flex-wrap gap-3">
          <input
            type="text"
            [(ngModel)]="promoCode"
            placeholder="Code promo"
            class="w-full sm:flex-1 bg-slate-900/40 border border-white/20 text-white px-4 py-3 rounded-lg placeholder-gray-500 focus:border-emerald-400 outline-none transition"
          />
          <button
            type="button"
            (click)="applyPromo()"
            [disabled]="(promoLoading$ | async) || !promoCode.trim()"
            class="bg-gradient-to-r from-emerald-500 to-cyan-500 hover:from-emerald-400 hover:to-cyan-400 disabled:from-gray-600 disabled:to-gray-600 text-white px-5 py-3 rounded-lg font-semibold transition flex items-center justify-center"
          >
            {{ (promoLoading$ | async) ? 'Application en cours…' : 'Appliquer' }}
          </button>
        </div>
        <p *ngIf="promoError$ | async as error" class="text-xs text-rose-300">
          {{ error }}
        </p>
        <ng-container *ngIf="appliedPromos$ | async as promos">
          <div *ngIf="promos.length" class="flex flex-wrap gap-2 text-xs text-emerald-200">
            <span
              *ngFor="let promo of promos"
              class="bg-emerald-600/20 border border-emerald-500/40 px-3 py-1 rounded-full"
            >
              {{ promo }}
            </span>
            <button type="button" (click)="clearPromo()" class="underline">Supprimer</button>
          </div>
        </ng-container>
        <ng-container *ngIf="breakdown$ | async as breakdown">
          <div class="flex justify-between text-gray-300">
            <span>Sous-total</span>
            <span>€{{ breakdown.itemsTotal.toFixed(2) }}</span>
          </div>
          <div class="flex justify-between text-gray-300">
            <span>Remise(s)</span>
            <span class="text-emerald-400">-€{{ breakdown.discount.toFixed(2) }}</span>
          </div>
          <div class="flex justify-between text-gray-300">
            <span>Frais de port</span>
            <span>€{{ breakdown.shipping.toFixed(2) }}</span>
          </div>
          <div class="flex justify-between text-gray-300">
            <span>Taxes</span>
            <span>€{{ breakdown.taxes.toFixed(2) }}</span>
          </div>
          <div class="flex justify-between border-t border-white/10 pt-4 text-lg font-bold">
            <span class="text-white">Total</span>
            <span class="bg-linear-to-r from-blue-400 to-emerald-400 bg-clip-text text-transparent">
              €{{ breakdown.grandTotal.toFixed(2) }}
            </span>
          </div>
        </ng-container>
      </div>

      <!-- Shipping Info -->
      <div class="bg-emerald-600/10 border border-emerald-500/30 rounded-2xl p-4 text-sm text-emerald-300">
        <p class="font-semibold mb-2">📦 Shipping Information</p>
        <p>Standard delivery: 2-3 business days</p>
        <p class="text-xs text-gray-400 mt-1">Free shipping on orders over €50</p>
      </div>

      <!-- Navigation -->
      <div class="flex gap-4">
        <button
          type="button"
          routerLink="/shop/products"
          class="flex-1 bg-white/10 hover:bg-white/20 border border-white/20 text-white py-3 px-4 rounded-lg font-semibold transition"
        >
          ← Continue Shopping
        </button>
        <button
          type="button"
          (click)="onNextStep()"
          class="flex-1 bg-linear-to-r from-blue-600 to-emerald-600 hover:from-blue-500 hover:to-emerald-500 text-white py-3 px-4 rounded-lg font-semibold transition"
        >
          Continue to Address →
        </button>
      </div>
    </div>
  `,
  styles: [],
})
export class CheckoutSummaryComponent {
  @Output() nextStep = new EventEmitter<void>();

  items$: Observable<CartItem[]>;
  breakdown$: Observable<CartPromoResult>;
  promoLoading$: Observable<boolean>;
  promoError$: Observable<string | null>;
  appliedPromos$: Observable<string[]>;
  promoCode = '';

  constructor(private store: Store) {
    this.items$ = this.store.select(selectCartItems);
    this.breakdown$ = this.store.select(selectCartBreakdown);
    this.promoLoading$ = this.store.select(selectPromoLoading);
    this.promoError$ = this.store.select(selectPromoError);
    this.appliedPromos$ = this.store.select(selectAppliedPromos);
  }

  applyPromo(): void {
    const code = this.promoCode?.trim();
    if (!code) {
      return;
    }
    this.store.dispatch(CartActions.applyPromoCode({ code }));
  }

  clearPromo(): void {
    this.store.dispatch(CartActions.clearCartPromo());
  }

  onNextStep(): void {
    this.nextStep.emit();
  }
}

import { Component, signal } from '@angular/core';
import { CommonModule, JsonPipe } from '@angular/common';
import { RouterLink } from '@angular/router';
import { MatButtonModule } from '@angular/material/button';
import { MatCardModule } from '@angular/material/card';

interface TokenResponse {
  access: string;
  refresh: string;
}
interface RefreshResponse {
  access: string;
}

@Component({
  standalone: true,
  selector: 'app-dev-auth',
  imports: [CommonModule, JsonPipe, RouterLink, MatButtonModule, MatCardModule],
  template: `
    <div class="min-h-screen bg-gradient-to-br from-slate-900 via-purple-900 to-slate-900">
      <!-- Navbar -->
      <nav class="backdrop-blur-md bg-white/10 border-b border-white/20 sticky top-0 z-50">
        <div class="mx-auto max-w-7xl px-6 py-4 flex justify-between items-center">
          <div class="flex items-center gap-3">
            <div class="w-10 h-10 bg-gradient-to-br from-purple-500 to-pink-500 rounded-lg flex items-center justify-center">
              <span class="text-white font-bold text-lg">🔐</span>
            </div>
            <h1 class="text-2xl font-bold text-white">Authentication Endpoint</h1>
          </div>
          
          <button 
            type="button"
            mat-button
            routerLink="/dev"
            class="text-gray-200 hover:text-white transition"
          >
            ← Back to Dev
          </button>
        </div>
      </nav>

      <!-- Main Content -->
      <div class="mx-auto max-w-2xl px-6 py-16">
        <div class="mb-12">
          <h2 class="text-5xl font-bold text-white mb-4">/api/auth/token/</h2>
          <p class="text-xl text-purple-200">Test authentication & token refresh endpoints</p>
        </div>

        <!-- Buttons -->
        <div class="flex gap-4 mb-8">
          <button
            type="button"
            (click)="login()"
            class="bg-blue-600 hover:bg-blue-700 text-white flex-1 py-3 px-4 text-lg font-semibold rounded-lg transition"
          >
            POST /token (Login)
          </button>
          <button
            type="button"
            (click)="refresh()"
            class="bg-emerald-600 hover:bg-emerald-700 text-white flex-1 py-3 px-4 text-lg font-semibold rounded-lg transition"
          >
            POST /refresh
          </button>
        </div>

        <!-- Response Section -->
        <div class="space-y-6">
          @if (loginResp(); as r) {
            <div class="rounded-2xl bg-white/5 backdrop-blur-md border border-white/10 p-6">
              <h3 class="text-lg font-bold text-white mb-4">Login Response</h3>
              <pre class="rounded-lg bg-slate-950/50 p-4 text-sm text-green-300 overflow-x-auto">{{ r | json }}</pre>
            </div>
          }

          @if (refreshResp(); as rr) {
            <div class="rounded-2xl bg-white/5 backdrop-blur-md border border-white/10 p-6">
              <h3 class="text-lg font-bold text-white mb-4">Refresh Response</h3>
              <pre class="rounded-lg bg-slate-950/50 p-4 text-sm text-green-300 overflow-x-auto">{{ rr | json }}</pre>
            </div>
          }

          @if (err()) {
            <div class="rounded-2xl bg-red-500/20 border border-red-500/50 p-6">
              <p class="text-red-200 font-medium flex items-center gap-2">
                <span class="text-lg">⚠️</span>
                {{ err() }}
              </p>
            </div>
          }
        </div>
      </div>
    </div>
  `,
  styles: [`
    :host ::ng-deep .mat-mdc-button {
      text-transform: none !important;
    }
  `]
})
export class DevAuthComponent {
  readonly loginResp = signal<TokenResponse | null>(null);
  readonly refreshResp = signal<RefreshResponse | null>(null);
  readonly err = signal<string | null>(null);

  async login(): Promise<void> {
    this.err.set(null);
    this.loginResp.set(null);
    const res = await fetch('/api/auth/token/', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ username: 'demo', password: 'demo' }),
    });
    if (!res.ok) {
      this.err.set(`${res.status} ${res.statusText}`);
      return;
    }
    const data = (await res.json()) as TokenResponse;
    this.loginResp.set(data);
  }

  async refresh(): Promise<void> {
    this.err.set(null);
    this.refreshResp.set(null);
    const res = await fetch('/api/auth/token/refresh/', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ refresh: 'mock-refresh-token' }),
    });
    if (!res.ok) {
      this.err.set(`${res.status} ${res.statusText}`);
      return;
    }
    const data = (await res.json()) as RefreshResponse;
    this.refreshResp.set(data);
  }
}

import { Component, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { RouterLink } from '@angular/router';
import { MatButtonModule } from '@angular/material/button';
import { products } from '../../mocks/data';

interface ValidationSummary {
  product_id: number;
  requested: number;
  available: number;
}

@Component({
  standalone: true,
  selector: 'app-dev-cart',
  imports: [CommonModule, FormsModule, RouterLink, MatButtonModule],
  template: `
    <div class="min-h-screen bg-gradient-to-br from-slate-900 via-purple-900 to-slate-900">
      <nav class="backdrop-blur-md bg-white/10 border-b border-white/20 sticky top-0 z-50">
        <div class="mx-auto max-w-7xl px-6 py-4 flex justify-between items-center">
          <div class="flex items-center gap-3">
            <div class="w-10 h-10 bg-gradient-to-br from-orange-500 to-amber-500 rounded-lg flex items-center justify-center">
              <span class="text-white font-bold text-lg">🧺</span>
            </div>
            <h1 class="text-2xl font-bold text-white">Cart Validation Endpoint</h1>
          </div>
          <button type="button" mat-button routerLink="/dev" class="text-gray-200 hover:text-white transition">
            ← Back to Dev
          </button>
        </div>
      </nav>

      <div class="mx-auto max-w-3xl px-6 py-16 space-y-10">
        <div>
          <h2 class="text-4xl font-bold text-white">POST /api/cart/validate-stock/</h2>
          <p class="text-sm text-gray-300">Simule la validation des quantités avant d'ajouter au panier.</p>
        </div>

        <form class="space-y-4" (submit)="$event.preventDefault(); validateStock()">
          <div class="grid grid-cols-2 gap-4">
            <label class="flex flex-col gap-1 text-sm text-gray-300">
              Produit
              <select
                [(ngModel)]="productId"
                name="productId"
                class="bg-slate-950/60 border border-white/10 rounded-lg px-3 py-2 text-white"
              >
                <option *ngFor="let item of availableProducts" [ngValue]="item.id">
                  {{ item.name }}
                </option>
              </select>
            </label>
            <label class="flex flex-col gap-1 text-sm text-gray-300">
              Quantity
              <input type="number" min="1" [(ngModel)]="quantity" name="quantity" class="bg-white/5 border border-white/20 rounded-lg px-3 py-2 text-white" />
            </label>
          </div>
          <button type="submit" class="w-full bg-emerald-600 hover:bg-emerald-700 text-white py-3 rounded-lg font-semibold transition">
            Validate Stock
          </button>
        </form>

        <div *ngIf="error()" class="rounded-2xl bg-red-500/20 border border-red-500/50 p-4 text-sm text-red-200">
          {{ error() }}
        </div>

        <div *ngIf="response() as resp" class="rounded-2xl bg-white/5 border border-white/10 p-6 space-y-3">
          <div class="flex items-center justify-between">
            <span class="text-sm text-gray-300">Status</span>
            <span class="text-sm text-emerald-200">{{ resp.valid ? 'Validated' : 'Invalid' }}</span>
          </div>
          <p class="text-sm text-gray-300">{{ resp.message }}</p>
          <div *ngIf="resp.summary.length">
            <h3 class="text-sm uppercase tracking-[0.2em] text-purple-200">Summary</h3>
            <div class="grid gap-2 text-sm text-white">
              <div *ngFor="let item of resp.summary" class="rounded-lg bg-slate-950/60 p-3 border border-white/10">
                <p>{{ productName(item.product_id) }}</p>
                <p class="text-xs text-gray-300">Requested: {{ item.requested }}, Available: {{ item.available }}</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  `,
})
export class DevCartComponent {
  readonly availableProducts = products;
  productId = this.availableProducts[0]?.id ?? 1;
  quantity = 1;

  readonly response = signal<{ valid: boolean; message: string; summary: ValidationSummary[] } | null>(null);
  readonly error = signal<string | null>(null);

  productName(productId: number) {
    return this.availableProducts.find((product) => product.id === productId)?.name ?? `Product #${productId}`;
  }

  async validateStock(): Promise<void> {
    this.error.set(null);
    this.response.set(null);
    const res = await fetch('/api/cart/validate-stock/', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ items: [{ productId: this.productId, quantity: this.quantity }] }),
    });
    if (!res.ok) {
      const message = (await res.json()).detail ?? `${res.status} ${res.statusText}`;
      this.error.set(message);
      return;
    }
    this.response.set(await res.json());
  }
}

import { Component, signal } from '@angular/core';
