import { Component, signal } from '@angular/core';
import { CommonModule, JsonPipe } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { RouterLink } from '@angular/router';
import { MatButtonModule } from '@angular/material/button';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';

interface Product {
  id: number;
  name: string;
  price: number;
  created_at: string;
  imageUrl?: string;
}
interface Paginated<T> {
  count: number;
  next: string | null;
  previous: string | null;
  results: T[];
}

@Component({
  standalone: true,
  selector: 'app-dev-products',
  imports: [CommonModule, JsonPipe, FormsModule, RouterLink, MatButtonModule, MatFormFieldModule, MatInputModule],
  template: `
    <div class="min-h-screen bg-gradient-to-br from-slate-900 via-purple-900 to-slate-900">
      <!-- Navbar -->
      <nav class="backdrop-blur-md bg-white/10 border-b border-white/20 sticky top-0 z-50">
        <div class="mx-auto max-w-7xl px-6 py-4 flex justify-between items-center">
          <div class="flex items-center gap-3">
            <div class="w-10 h-10 bg-gradient-to-br from-purple-500 to-pink-500 rounded-lg flex items-center justify-center">
              <span class="text-white font-bold text-lg">📦</span>
            </div>
            <h1 class="text-2xl font-bold text-white">Products Endpoint</h1>
          </div>
          
          <button 
            type="button"
            mat-button
            routerLink="/dev"
            class="text-gray-200 hover:text-white transition"
          >
            ← Back to Dev
          </button>
        </div>
      </nav>

      <!-- Main Content -->
      <div class="mx-auto max-w-4xl px-6 py-16">
        <div class="mb-12">
          <h2 class="text-5xl font-bold text-white mb-4">GET /api/products/</h2>
          <p class="text-xl text-purple-200">Test products endpoint with filters</p>
        </div>

        <!-- Filter Form -->
        <div class="bg-white/5 backdrop-blur-md border border-white/10 rounded-2xl p-8 mb-8">
          <form
            class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4"
            (submit)="$event.preventDefault(); load()"
          >
            <div class="bg-white/10 rounded-lg border border-white/20 px-3 py-2">
              <label class="text-xs text-gray-300 block mb-1">Page</label>
              <input type="number" [(ngModel)]="page" name="page" class="w-full bg-transparent text-white outline-none" />
            </div>

            <div class="bg-white/10 rounded-lg border border-white/20 px-3 py-2">
              <label class="text-xs text-gray-300 block mb-1">Page Size</label>
              <input type="number" [(ngModel)]="pageSize" name="pageSize" class="w-full bg-transparent text-white outline-none" />
            </div>

            <div class="bg-white/10 rounded-lg border border-white/20 px-3 py-2">
              <label class="text-xs text-gray-300 block mb-1">Min Rating</label>
              <input type="number" step="0.1" [(ngModel)]="minRating" name="minRating" class="w-full bg-transparent text-white outline-none" />
            </div>

            <div class="bg-white/10 rounded-lg border border-white/20 px-3 py-2">
              <label class="text-xs text-gray-300 block mb-1">Ordering</label>
              <input type="text" [(ngModel)]="ordering" name="ordering" placeholder="-created_at|price|name" class="w-full bg-transparent text-white outline-none text-sm" />
            </div>

            <button
              type="button"
              (click)="load()"
              class="bg-blue-600 hover:bg-blue-700 text-white py-2 px-4 rounded-lg font-semibold transition"
            >
              Fetch
            </button>
          </form>
        </div>

        <!-- Response Section -->
        @if (resp(); as r) {
          <div class="rounded-2xl bg-white/5 backdrop-blur-md border border-white/10 p-6">
            <div class="mb-4 flex justify-between items-center">
              <h3 class="text-lg font-bold text-white">Response</h3>
              <div class="text-sm text-purple-200">Count: <span class="font-bold text-white">{{ r.count }}</span></div>
            </div>
            <pre class="rounded-lg bg-slate-950/50 p-4 text-sm text-green-300 overflow-x-auto">{{ r | json }}</pre>
          </div>
        }

        @if (err()) {
          <div class="rounded-2xl bg-red-500/20 border border-red-500/50 p-6">
            <p class="text-red-200 font-medium flex items-center gap-2">
              <span class="text-lg">⚠️</span>
              {{ err() }}
            </p>
          </div>
        }
      </div>
    </div>
  `,
  styles: [`
    :host ::ng-deep .mat-mdc-button {
      text-transform: none !important;
    }
  `]
})
export class DevProductsComponent {
  page = 1;
  pageSize = 10;
  minRating = 0;
  ordering = '-created_at';

  readonly resp = signal<Paginated<Product> | null>(null);
  readonly err = signal<string | null>(null);

  async load(): Promise<void> {
    this.err.set(null);
    this.resp.set(null);
    const q = new URLSearchParams({
      page: String(this.page),
      page_size: String(this.pageSize),
      min_rating: String(this.minRating),
      ordering: this.ordering,
    });
    const res = await fetch(`/api/products/?${q.toString()}`);
    if (!res.ok) {
      this.err.set(`${res.status} ${res.statusText}`);
      return;
    }
    const data = (await res.json()) as Paginated<Product>;
    this.resp.set(data);
  }
}

import { Component, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { RouterLink } from '@angular/router';
import { MatButtonModule } from '@angular/material/button';

interface UserProfile {
  fullName: string;
  email: string;
  preferences: {
    newsletter: boolean;
    preferredRating: number;
  };
}

@Component({
  standalone: true,
  selector: 'app-dev-profile',
  imports: [CommonModule, FormsModule, RouterLink, MatButtonModule],
  template: `
    <div class="min-h-screen bg-gradient-to-br from-slate-900 via-purple-900 to-slate-900">
      <nav class="backdrop-blur-md bg-white/10 border-b border-white/20 sticky top-0 z-50">
        <div class="mx-auto max-w-7xl px-6 py-4 flex justify-between items-center">
          <div class="flex items-center gap-3">
            <div class="w-10 h-10 bg-gradient-to-br from-purple-500 to-pink-500 rounded-lg flex items-center justify-center">
              <span class="text-white font-bold text-lg">👤</span>
            </div>
            <h1 class="text-2xl font-bold text-white">User Profile Endpoint</h1>
          </div>
          <button
            type="button"
            mat-button
            routerLink="/dev"
            class="text-gray-200 hover:text-white transition"
          >
            ← Back to Dev
          </button>
        </div>
      </nav>

      <div class="mx-auto max-w-3xl px-6 py-16 space-y-8">
        <div class="space-y-2">
          <h2 class="text-4xl font-bold text-white">GET /api/me/</h2>
          <p class="text-sm text-gray-300">Reloads the mocked user profile, including preferences.</p>
        </div>
        <div class="space-y-4">
          <button
            type="button"
            (click)="loadProfile()"
            class="w-full bg-blue-600 hover:bg-blue-700 text-white py-3 rounded-lg font-semibold transition"
          >
            Fetch Profile
          </button>
          <div *ngIf="profile() as current; else profilePlaceholder">
            <pre
              class="rounded-2xl bg-slate-950/70 p-4 text-sm text-emerald-200 overflow-x-auto"
            >
              {{ current | json }}
            </pre>
          </div>
          <ng-template #profilePlaceholder>
            <p class="text-gray-400 text-sm">Click "Fetch Profile" to load the current user.</p>
          </ng-template>
        </div>

        <div class="space-y-2">
          <h2 class="text-4xl font-bold text-white">PATCH /api/me/</h2>
          <p class="text-sm text-gray-300">Send a partial update (preferences, full name, etc.).</p>
        </div>
        <form class="grid gap-4" (submit)="$event.preventDefault(); updateProfile()">
          <input
            type="text"
            [(ngModel)]="updatePayload.fullName"
            name="fullName"
            placeholder="Full Name"
            class="w-full bg-white/5 border border-white/20 rounded-lg px-4 py-3 text-white"
          />
          <div class="grid grid-cols-2 gap-4">
            <label class="flex flex-col space-y-1 text-sm text-gray-300">
              Newsletter
              <select
                [(ngModel)]="updatePayload.preferences.newsletter"
                name="newsletter"
                class="bg-slate-950/60 border border-white/10 rounded-lg px-3 py-2 text-white"
              >
                <option [value]="true">Enabled</option>
                <option [value]="false">Disabled</option>
              </select>
            </label>
            <label class="flex flex-col space-y-1 text-sm text-gray-300">
              Preferred Rating
              <input
                type="number"
                [(ngModel)]="updatePayload.preferences.preferredRating"
                name="preferredRating"
                min="1"
                max="5"
                step="1"
                class="bg-white/5 border border-white/20 rounded-lg px-3 py-2 text-white"
              />
            </label>
          </div>
          <button
            type="submit"
            class="w-full bg-emerald-600 hover:bg-emerald-700 text-white py-3 rounded-lg font-semibold transition"
          >
            Apply Update
          </button>
        </form>
        <ng-container *ngIf="updateResp() as resp">
          <pre class="rounded-2xl bg-slate-950/70 p-4 text-sm text-emerald-200 overflow-x-auto">
            {{ resp | json }}
          </pre>
        </ng-container>
        <div *ngIf="error() as message" class="rounded-2xl bg-red-500/20 border border-red-500/50 p-4 text-sm text-red-200">
          {{ message }}
        </div>
      </div>
    </div>
  `,
  styles: [
    `:host ::ng-deep .mat-mdc-button { text-transform: none !important; }`
  ]
})
export class DevProfileComponent {
  readonly profile = signal<UserProfile | null>(null);
  readonly updateResp = signal<UserProfile | null>(null);
  readonly error = signal<string | null>(null);

  updatePayload: Pick<UserProfile, 'preferences'> & Partial<Pick<UserProfile, 'fullName'>> = {
    fullName: '',
    preferences: {
      newsletter: true,
      preferredRating: 4,
    },
  };

  async loadProfile(): Promise<void> {
    this.error.set(null);
    const res = await fetch('/api/me/');
    if (!res.ok) {
      this.error.set(`${res.status} ${res.statusText}`);
      return;
    }
    const json = (await res.json()) as UserProfile;
    this.profile.set(json);
  }

  async updateProfile(): Promise<void> {
    this.error.set(null);
    this.updateResp.set(null);
    const res = await fetch('/api/me/', {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(this.updatePayload),
    });
    if (!res.ok) {
      this.error.set(`${res.status} ${res.statusText}`);
      return;
    }
    this.updateResp.set((await res.json()) as UserProfile);
  }
}

import { Component, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { RouterLink } from '@angular/router';
import { MatButtonModule } from '@angular/material/button';
import { Review } from '../state/reviews/review.model';
import { products } from '../../mocks/data';

@Component({
  standalone: true,
  selector: 'app-dev-reviews',
  imports: [CommonModule, FormsModule, RouterLink, MatButtonModule],
  template: `
    <div class="min-h-screen bg-gradient-to-br from-slate-900 via-purple-900 to-slate-900">
      <nav class="backdrop-blur-md bg-white/10 border-b border-white/20 sticky top-0 z-50">
        <div class="mx-auto max-w-7xl px-6 py-4 flex justify-between items-center">
          <div class="flex items-center gap-3">
            <div class="w-10 h-10 bg-gradient-to-br from-pink-500 to-purple-500 rounded-lg flex items-center justify-center">
              <span class="text-white font-bold text-lg">⭐</span>
            </div>
            <h1 class="text-2xl font-bold text-white">Reviews Endpoint</h1>
          </div>
          <button type="button" mat-button routerLink="/dev" class="text-gray-200 hover:text-white transition">
            ← Back to Dev
          </button>
        </div>
      </nav>

      <div class="mx-auto max-w-4xl px-6 py-16 space-y-10">
        <div>
          <h2 class="text-4xl font-bold text-white">GET /api/products/:id/reviews/</h2>
          <p class="text-sm text-gray-300">Récupère les avis filtrés et triés.</p>
        </div>

        <form class="grid grid-cols-1 md:grid-cols-3 gap-4" (submit)="$event.preventDefault(); loadReviews()">
          <label class="flex flex-col gap-1 text-sm text-gray-300">
            Produit
            <select
              [(ngModel)]="productId"
              name="productId"
              class="bg-slate-950/60 border border-white/10 rounded-lg px-3 py-2 text-white"
            >
              <option *ngFor="let item of availableProducts" [ngValue]="item.id">
                {{ item.name }}
              </option>
            </select>
          </label>
          <label class="flex flex-col gap-1 text-sm text-gray-300">
            Min Rating
            <input type="number" min="0" max="5" step="0.1" [(ngModel)]="minRating" name="minRating" class="bg-white/5 border border-white/20 rounded-lg px-3 py-2 text-white" />
          </label>
          <label class="flex flex-col gap-1 text-sm text-gray-300">
            Sort By
            <select [(ngModel)]="sortBy" name="sortBy" class="bg-slate-950/60 border border-white/10 rounded-lg px-3 py-2 text-white">
              <option value="recent">Recent</option>
              <option value="rating">Rating</option>
            </select>
          </label>
          <button type="submit" class="md:col-span-3 bg-blue-600 hover:bg-blue-700 text-white py-2 rounded-lg font-semibold transition">
            Load Reviews
          </button>
        </form>

        <div *ngIf="reviews() as list" class="space-y-4">
          <div class="rounded-2xl bg-white/5 border border-white/10 p-4">
            <p class="text-sm text-gray-300">{{ stats()?.count ?? 0 }} avis • Moyenne {{ stats()?.average ?? 0 | number:'1.1-1' }}</p>
          </div>
          <div class="space-y-3">
            <div *ngFor="let review of list" class="rounded-2xl bg-slate-950/70 border border-white/10 p-4 space-y-2">
              <div class="flex items-center justify-between">
                <p class="text-white font-semibold">{{ review.author }}</p>
                <p class="text-sm text-amber-300">{{ review.rating }}★</p>
              </div>
              <p class="text-sm text-gray-300">{{ review.comment }}</p>
              <p class="text-xs text-gray-500">{{ review.createdAt }}</p>
            </div>
          </div>
        </div>

        <div class="rounded-2xl bg-white/5 border border-white/10 p-6 space-y-4">
          <h3 class="text-lg font-bold text-white">POST /api/products/:id/reviews/</h3>
          <form class="space-y-3" (submit)="$event.preventDefault(); submitReview()">
            <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
              <input type="text" placeholder="Author" [(ngModel)]="author" name="author" class="bg-white/5 border border-white/20 rounded-lg px-3 py-2 text-white" />
              <input type="number" placeholder="Rating" min="1" max="5" [(ngModel)]="rating" name="rating" class="bg-white/5 border border-white/20 rounded-lg px-3 py-2 text-white" />
            </div>
            <textarea
              placeholder="Comment"
              [(ngModel)]="comment"
              name="comment"
              rows="3"
              class="w-full bg-white/5 border border-white/20 rounded-lg px-3 py-2 text-white"
            ></textarea>
            <button type="submit" class="w-full bg-emerald-600 hover:bg-emerald-700 text-white py-2 rounded-lg font-semibold transition">
              Submit Review
            </button>
          </form>
          <div *ngIf="reviewResponse()" class="rounded-lg bg-slate-950/60 border border-white/10 p-3 text-sm text-emerald-200">
            {{ reviewResponse() | json }}
          </div>
          <div *ngIf="reviewError()" class="rounded-lg bg-red-500/20 border border-red-500/50 p-3 text-sm text-red-200">
            {{ reviewError() }}
          </div>
        </div>
      </div>
    </div>
  `,
})
export class DevReviewsComponent {
  readonly availableProducts = products;
  productId = this.availableProducts[0]?.id ?? 1;
  minRating = 0;
  sortBy: 'recent' | 'rating' = 'recent';

  author = '';
  rating = 5;
  comment = '';

  private statsSignal = signal<{ average: number; count: number } | null>(null);
  readonly reviews = signal<Review[] | null>(null);
  readonly reviewResponse = signal<Record<string, unknown> | null>(null);
  readonly reviewError = signal<string | null>(null);

  stats() {
    return this.statsSignal();
  }

  async loadReviews(): Promise<void> {
    this.reviewError.set(null);
    this.reviewResponse.set(null);
    const query = new URLSearchParams({
      min_rating: String(this.minRating),
      sort_by: this.sortBy,
    });
    const res = await fetch(`/api/products/${this.productId}/reviews/?${query.toString()}`);
    if (!res.ok) {
      this.reviewError.set(`${res.status} ${res.statusText}`);
      return;
    }
    const json = await res.json();
    this.reviews.set(json.results);
    this.statsSignal.set({ average: json.average, count: json.count });
  }

  async submitReview(): Promise<void> {
    this.reviewError.set(null);
    this.reviewResponse.set(null);
    const payload = {
      author: this.author,
      rating: this.rating,
      comment: this.comment,
    };
    const res = await fetch(`/api/products/${this.productId}/reviews/`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    const data = await res.json();
    if (!res.ok) {
      this.reviewError.set(data.detail || `${res.status} ${res.statusText}`);
      return;
    }
    this.reviewResponse.set(data);
    await this.loadReviews();
  }
}

