import { Component, EventEmitter, Input, OnChanges, Output, SimpleChanges } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';

@Component({
  standalone: true,
  selector: 'app-user-profile-form',
  imports: [CommonModule, ReactiveFormsModule],
  template: `
    <section class="max-w-xl mx-auto bg-white/5 border border-white/10 rounded-3xl p-6 space-y-6 shadow-xl backdrop-blur-lg">
      <header>
        <p class="text-xs uppercase tracking-[0.3em] text-indigo-200">Profile</p>
        <h2 class="text-3xl font-bold text-white">{{ title }}</h2>
        <p class="text-sm text-gray-300">Mettez à jour vos informations personnelles.</p>
      </header>

      <form
        [formGroup]="profileForm"
        (ngSubmit)="submitProfile.emit(getPayload())"
        class="space-y-5"
      >
        <label class="block space-y-1 text-sm text-gray-200">
          <span>Name</span>
          <input
            formControlName="name"
            class="w-full px-4 py-3 bg-slate-950/30 border border-white/20 rounded-xl focus:border-indigo-400 focus:ring-2 focus:ring-indigo-500 outline-none"
          />
        </label>

        <label class="block space-y-1 text-sm text-gray-200">
          <span>Email</span>
          <input
            formControlName="email"
            type="email"
            class="w-full px-4 py-3 bg-slate-950/30 border border-white/20 rounded-xl focus:border-indigo-400 focus:ring-2 focus:ring-indigo-500 outline-none"
          />
        </label>

        <label class="flex items-center gap-3 mt-2 text-sm text-gray-200">
          <input type="checkbox" formControlName="newsletter" class="h-4 w-4 rounded border-white/40" />
          Receive newsletter & updates
        </label>

        <button
          type="submit"
          class="w-full bg-gradient-to-r from-sky-500 to-indigo-600 text-white font-semibold py-3 rounded-2xl hover:opacity-90 transition"
        >
          Save Profile
        </button>
      </form>
    </section>
  `,
})
export class UserProfileFormComponent implements OnChanges {
  @Input() title = 'User Profile';
  @Input() name = 'Jane Doe';
  @Input() email = 'jane.doe@example.com';
  @Input() newsletter = true;
  @Output() submitProfile = new EventEmitter<{ name: string; email: string; newsletter: boolean }>();

  profileForm: FormGroup;

  constructor(private fb: FormBuilder) {
    this.profileForm = this.fb.group({
      name: [this.name, Validators.required],
      email: [this.email, [Validators.required, Validators.email]],
      newsletter: [this.newsletter],
    });
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (this.profileForm) {
      this.profileForm.patchValue({
        name: this.name,
        email: this.email,
        newsletter: this.newsletter,
      });
    }
  }

  getPayload(): { name: string; email: string; newsletter: boolean } {
    const { name, email, newsletter } = this.profileForm.value as {
      name: string | null;
      email: string | null;
      newsletter: boolean | null;
    };

    return {
      name: name ?? '',
      email: email ?? '',
      newsletter: newsletter ?? false,
    };
  }
}

import { Component, EventEmitter, Input, Output } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
  standalone: true,
  selector: 'app-wishlist-button',
  imports: [CommonModule],
  template: `
    <button
      type="button"
      (click)="toggleWishlist.emit()"
      class="px-5 py-2 rounded-full font-semibold transition inline-flex items-center gap-2 border-2"
      [class.border-pink-400]="active"
      [class.border-white/40]="!active"
      [class.text-pink-200]="active"
      [class.text-white]="!active"
      [class.bg-pink-500/10]="active"
    >
      <span [class.text-xl]="size === 'large'">{{ active ? '💖' : '🤍' }}</span>
      <span>{{ active ? activeLabel : label }}</span>
    </button>
  `,
})
export class WishlistButtonComponent {
  @Input() active = false;
  @Input() label = 'Save for later';
  @Input() activeLabel = 'Wishlisted';
  @Input() size: 'small' | 'medium' | 'large' = 'medium';
  @Output() toggleWishlist = new EventEmitter<void>();
}

import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink } from '@angular/router';
import { Store } from '@ngrx/store';
import { selectWishlistCount } from '../../state/wishlist/wishlist.selectors';
import { Observable } from 'rxjs';

@Component({
  standalone: true,
  selector: 'app-wishlist-icon',
  imports: [CommonModule, RouterLink],
  template: `
    <div class="relative">
      <a
        routerLink="/account/wishlist"
        aria-label="Afficher la wishlist"
        class="flex items-center gap-2 bg-white/10 hover:bg-white/20 border border-white/20 px-3 py-2 rounded-lg transition"
      >
        <span class="text-xl">💖</span>
        @if ((wishlistCount$ | async); as count) {
          @if (count > 0) {
            <span class="text-sm font-semibold text-white">My Wishlist</span>
            <span
              class="absolute -top-2 -right-2 bg-linear-to-r from-pink-500 to-rose-500 text-white text-xs font-bold rounded-full w-6 h-6 flex items-center justify-center"
            >
              {{ count }}
            </span>
          } @else {
            <span class="text-sm font-semibold text-gray-400">Empty</span>
          }
        }
      </a>
    </div>
  `,
})
export class WishlistIconComponent {
  wishlistCount$: Observable<number>;

  constructor(private store: Store) {
    this.wishlistCount$ = this.store.select(selectWishlistCount);
  }
}

import { ChangeDetectionStrategy, Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink } from '@angular/router';
import { MatButtonModule } from '@angular/material/button';
import { MatCardModule } from '@angular/material/card';
import { MatSnackBar, MatSnackBarModule } from '@angular/material/snack-bar';
import { Store } from '@ngrx/store';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';
import * as ProductsActions from '../state/products/products.actions';
import * as CartActions from '../state/cart/cart.actions';
import * as WishlistActions from '../state/wishlist/wishlist.actions';
import { selectCartItems } from '../state/cart/cart.selectors';
import { selectWishlistCount, selectWishlistProducts } from '../state/wishlist/wishlist.selectors';
import { selectIsAuthenticated } from '../state/auth/auth.selectors';
import * as AuthActions from '../state/auth/auth.actions';
import { CartIconComponent } from '../components/cart-icon/cart-icon.component';
import { WishlistIconComponent } from '../components/wishlist-icon/wishlist-icon.component';

interface Product {
  id: number;
  name: string;
  description: string;
  price: number;
  avgRating: number;
  stock: number;
  created_at: string;
  imageUrl?: string;
}

@Component({
  standalone: true,
  selector: 'app-wishlist-page',
  imports: [
    CommonModule,
    RouterLink,
    MatCardModule,
    MatButtonModule,
    MatSnackBarModule,
    CartIconComponent,
    WishlistIconComponent,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `
    <div class="min-h-screen bg-linear-to-br from-slate-900 via-purple-900 to-slate-900">
      <nav class="backdrop-blur-md bg-white/10 border-b border-white/20 sticky top-0 z-50">
        <div class="mx-auto max-w-7xl px-6 py-4">
          <div class="flex justify-between items-center">
            <div class="flex items-center gap-3">
              <div class="w-10 h-10 bg-linear-to-br from-purple-500 to-pink-500 rounded-lg flex items-center justify-center">
                <span class="text-white font-bold text-lg">🛍️</span>
              </div>
              <h1 class="text-2xl font-bold text-white">My Shop</h1>
            </div>

            <div class="hidden md:flex items-center gap-6">
              <button
                type="button"
                mat-button
                routerLink="/"
                class="text-gray-200 hover:text-white transition font-medium"
              >
                Home
              </button>
              <button
                type="button"
                mat-button
                routerLink="/shop/products"
                class="text-gray-200 hover:text-white transition font-medium"
              >
                Products
              </button>
              <button
                type="button"
                mat-button
                routerLink="/shop/rating"
                class="text-gray-200 hover:text-white transition font-medium"
              >
                Ratings
              </button>
              <button
                type="button"
                mat-button
                *ngIf="isAuthenticated$ | async"
                routerLink="/account/profile"
                class="text-gray-200 hover:text-white transition font-medium"
              >
                Mon Compte
              </button>
              <button
                type="button"
                mat-button
                routerLink="/dev"
                class="text-gray-200 hover:text-white transition font-medium"
              >
                Dev
              </button>
            </div>

            <div class="flex items-center gap-4">
              <app-cart-icon></app-cart-icon>
              <app-wishlist-icon></app-wishlist-icon>

              @if (isAuthenticated$ | async) {
                <div class="flex items-center gap-3 px-4 py-2 bg-green-500/20 border border-green-500/50 rounded-full">
                  <span class="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
                  <span class="text-green-200 font-medium text-sm">Authenticated</span>
                </div>
                <button
                  type="button"
                  mat-button
                  (click)="logout()"
                  class="text-red-300 hover:text-red-100 transition"
                >
                  Logout
                </button>
              } @else {
                <button
                  type="button"
                  mat-raised-button
                  routerLink="/login"
                  class="bg-purple-600 hover:bg-purple-700 text-white"
                >
                  Sign In
                </button>
              }
            </div>
          </div>
        </div>
      </nav>

      <div class="px-6 py-12">
        <div class="mx-auto max-w-6xl relative space-y-8">
          <div class="bg-white/5 backdrop-blur-md border border-white/10 rounded-3xl p-8 text-white">
            <div class="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
              <div>
                <p class="text-sm tracking-wide uppercase text-pink-200">Liste d'envies</p>
                <h1 class="text-4xl font-bold">Your Wishlist</h1>
                <p class="text-gray-400 mt-1">Keep favorite products for easy checkout.</p>
              </div>
              <div class="text-right">
                <p class="text-3xl font-bold bg-linear-to-r from-pink-500 to-purple-500 bg-clip-text text-transparent">{{ wishlistCount$ | async }}</p>
                <p class="text-sm text-gray-400">items saved</p>
              </div>
            </div>
          </div>

          @if ((wishlistProducts$ | async); as wishlistProducts) {
            @if (wishlistProducts.length > 0) {
              <div class="grid grid-cols-1 md:grid-cols-2 gap-6">
                @for (product of wishlistProducts; track product.id) {
                  <mat-card class="relative overflow-hidden border border-white/10 bg-transparent shadow-[0_35px_80px_-40px_rgba(15,23,42,0.9)]" style="background: transparent !important;">
                    <div class="relative z-10 p-6 space-y-5">
                      <div class="absolute inset-0 pointer-events-none border border-white/10 shadow-[inset_0_0_60px_rgba(255,255,255,0.05),0_10px_40px_-20px_rgba(15,23,42,0.8)]"></div>
                      <div>
