(value: string): Array<{ field: ProductSortableField; direction: 1 | -1 }> => {
  return value
    .split(/[|,]/)
    .map((token) => token.trim())
    .filter(Boolean)
    .map((token) => {
      const direction = token.startsWith('-') ? -1 : 1;
      const rawField = token.replace(/^[-+]/, '');
      if (!sortableFields.includes(rawField as ProductSortableField)) {
        return null;
      }
      return {
        field: rawField as ProductSortableField,
        direction,
      };
    })
    .filter((value): value is { field: ProductSortableField; direction: 1 | -1 } => !!value);
}

createReducer(
  initialState,
  on(CartActions.addItem, (state, { product, quantity }) => {
    const existingItem = state.items.find(item => item.id === product.id);

    if (existingItem) {
      // If item exists, increase quantity
      return {
        ...state,
        items: state.items.map(item =>
          item.id === product.id
            ? { ...item, quantity: item.quantity + quantity }
            : item
        ),
      };
    }

    // Add new item
    return {
      ...state,
      items: [...state.items, { ...product, quantity }],
    };
  }),

  on(CartActions.removeItem, (state, { productId }) => ({
    ...state,
    items: state.items.filter(item => item.id !== productId),
  })),

  on(CartActions.updateQuantity, (state, { productId, quantity }) => {
    if (quantity <= 0) {
      return {
        ...state,
        items: state.items.filter(item => item.id !== productId),
      };
    }

    return {
      ...state,
      items: state.items.map(item =>
        item.id === productId ? { ...item, quantity } : item
      ),
    };
  }),

  on(CartActions.clearCart, () => ({
    ...initialState,
  })),

  on(CartActions.loadCartFromStorage, (state, { items }) => ({
    ...state,
    items,
  })),
  on(CartActions.applyPromoCode, (state) => ({
    ...state,
    promoLoading: true,
    promoError: null,
  })),
  on(CartActions.applyPromoSuccess, (state, { result }) => ({
    ...state,
    promo: result,
    promoLoading: false,
